<?php declare(strict_types=1);require_once __DIR__.'/_common.php';$type=$_GET['type']??'projects';if(!in_array($type,['projects','news','events'],true))$type='projects';$id=max(0,(int)($_GET['id']??0));$error='';$langs=['en','fr','ar','de','it','es'];if(post()){verifyCsrf();$action=$_POST['action']??'';try{if($action==='delete'){if((int)($_POST['id']??0)<1)throw new RuntimeException('Choose a valid item to delete.');db()->prepare("DELETE FROM $type WHERE id=?")->execute([(int)$_POST['id']]);adminAudit('delete',$type,(int)$_POST['id']);flash('success','Content deleted.');redirect('content.php?type='.$type);}if($action==='save'){if(trim((string)($_POST['title_en']??''))==='')throw new RuntimeException('Please provide an English title before saving.');if($type==='projects'){$data=[];foreach($langs as $l)$data['title_'.$l]=clean('title_'.$l,255);foreach($langs as $l)$data['description_'.$l]=clean('description_'.$l,100000);$data['category']=clean('category',80);$data['status']=$_POST['status']??'active';$data['start_date']=clean('start_date',20)?:null;$data['end_date']=clean('end_date',20)?:null;$img=safeFileUpload('featured_image');if($img)$data['featured_image']=$img;$fields=array_keys($data);if($id){$set=implode(',',array_map(fn($f)=>"$f=?",$fields));db()->prepare("UPDATE projects SET $set WHERE id=?")->execute([...array_values($data),$id]);}else{if(!isset($data['featured_image']))$data['featured_image']=null;$fields=array_keys($data);db()->prepare('INSERT INTO projects('.implode(',',$fields).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')')->execute(array_values($data));$id=(int)db()->lastInsertId();}}elseif($type==='news'){$data=[];foreach($langs as $l)$data['title_'.$l]=clean('title_'.$l,255);foreach($langs as $l)$data['body_'.$l]=clean('body_'.$l,100000);$data['category']=clean('category',80);$data['is_published']=isset($_POST['is_published'])?1:0;$pub=clean('published_at',30);$data['published_at']=$pub?str_replace('T',' ',$pub).(strlen($pub)===16?':00':''):date('Y-m-d H:i:s');$img=safeFileUpload('featured_image');if($img)$data['featured_image']=$img;$data['author_id']=$admin['id'];$fields=array_keys($data);if($id){unset($data['author_id']);$fields=array_keys($data);$set=implode(',',array_map(fn($f)=>"$f=?",$fields));db()->prepare("UPDATE news SET $set WHERE id=?")->execute([...array_values($data),$id]);}else{if(!isset($data['featured_image']))$data['featured_image']=null;$fields=array_keys($data);db()->prepare('INSERT INTO news('.implode(',',$fields).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')')->execute(array_values($data));$id=(int)db()->lastInsertId();}}else{$data=[];foreach($langs as $l)$data['title_'.$l]=clean('title_'.$l,255);foreach($langs as $l)$data['description_'.$l]=clean('description_'.$l,100000);$data['location']=clean('location',255);$data['event_date']=clean('event_date',20);$data['event_time']=clean('event_time',20);$data['capacity']=($_POST['capacity']??'')!==''?(int)$_POST['capacity']:null;$data['is_published']=isset($_POST['is_published'])?1:0;$img=safeFileUpload('featured_image');if($img)$data['featured_image']=$img;$fields=array_keys($data);if($id){$set=implode(',',array_map(fn($f)=>"$f=?",$fields));db()->prepare("UPDATE events SET $set WHERE id=?")->execute([...array_values($data),$id]);}else{if(!isset($data['featured_image']))$data['featured_image']=null;$fields=array_keys($data);db()->prepare('INSERT INTO events('.implode(',',$fields).') VALUES('.implode(',',array_fill(0,count($fields),'?')).')')->execute(array_values($data));$id=(int)db()->lastInsertId();}}adminAudit($id?'update':'create',$type,$id);flash('success',$type==='projects'?'Project details saved.':(((int)($data['is_published']??1)===1)?'Content saved and published.':'Content saved as a draft.'));redirect('content.php?type='.$type);}}catch(Throwable $e){error_log($e->getMessage());$error='The content could not be saved. Check the form fields and try again.';}}$edit=null;if($id){$s=db()->prepare("SELECT * FROM $type WHERE id=?");$s->execute([$id]);$edit=$s->fetch();}$rows=db()->query("SELECT * FROM $type ORDER BY id DESC LIMIT 100")->fetchAll();$typeLabel=['projects'=>'Projects','news'=>'News','events'=>'Events'][$type];$pageTitle=$typeLabel.' admin';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">CRUD</p><h1 class="section-title"><?=e(ucfirst($type))?></h1></div><div class="admin-actions"><a class="btn ghost" href="content.php?type=projects">Projects</a><a class="btn ghost" href="content.php?type=news">News</a><a class="btn ghost" href="content.php?type=events">Events</a></div></div><?php if($error):?><div class="flash error" style="position:static;margin:15px 0"><?=e($error)?></div><?php endif;?><div class="form-shell" style="max-width:none"><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="save"><h2><?=$edit?'Edit':'Create'?> <?=e(match($type){'projects'=>'Project','news'=>'News','events'=>'Event',default=>'Content'})?></h2><?php $bodyKey=$type==='news'?'body':'description';?><div class="translation-editor" data-translation-editor><div class="translation-editor-heading"><strong>Content language</strong><span class="help">Edit English first. Use another language tab only when you have translated copy; untouched languages can stay empty.</span></div><div class="translation-tabs" role="tablist" aria-label="Content language"><?php foreach($langs as $l):?><button type="button" class="translation-tab <?= $l==='en'?'is-active':'' ?>" role="tab" aria-selected="<?= $l==='en'?'true':'false' ?>" data-language-tab="<?=$l?>"><?=strtoupper($l)?></button><?php endforeach;?></div><?php foreach($langs as $l):?><section class="translation-panel" role="tabpanel" data-language-panel="<?=$l?>" <?=$l==='en'?'':'hidden'?>><div class="field"><label for="title-<?=$l?>">Title · <?=strtoupper($l)?></label><input id="title-<?=$l?>" name="title_<?=$l?>" value="<?=e($edit['title_'.$l]??'')?>" <?=$l==='en'?'required':''?>></div><div class="field"><label for="body-<?=$l?>"><?=ucfirst($bodyKey)?> · <?=strtoupper($l)?></label><textarea id="body-<?=$l?>" name="<?=$bodyKey?>_<?=$l?>"><?=e($edit[$bodyKey.'_'.$l]??'')?></textarea></div></section><?php endforeach;?></div><div class="grid-3"><div class="field"><label>Category</label><input name="category" value="<?=e($edit['category']??'General')?>" required></div><?php if($type==='projects'):?><div class="field"><label>Status</label><select name="status"><option value="active" <?=($edit['status']??'active')==='active'?'selected':''?>>Active</option><option value="completed" <?=($edit['status']??'')==='completed'?'selected':''?>>Completed</option></select></div><div class="field"><label>Start date</label><input type="date" name="start_date" value="<?=e($edit['start_date']??'')?>"></div><div class="field"><label>End date</label><input type="date" name="end_date" value="<?=e($edit['end_date']??'')?>"></div><?php elseif($type==='news'):?><div class="field"><label>Publication date</label><input type="datetime-local" name="published_at" value="<?=e(isset($edit['published_at'])?date('Y-m-d\TH:i',strtotime($edit['published_at'])):date('Y-m-d\TH:i'))?>"></div><div class="field"><label><input type="checkbox" name="is_published" <?=(!isset($edit)||$edit['is_published'])?'checked':''?>> Published</label></div><?php else:?><div class="field"><label>Location</label><input name="location" value="<?=e($edit['location']??'')?>" required></div><div class="field"><label>Date</label><input type="date" name="event_date" value="<?=e($edit['event_date']??'')?>" required></div><div class="field"><label>Time</label><input type="time" name="event_time" value="<?=e($edit['event_time']??'')?>" required></div><div class="field"><label>Capacity (optional)</label><input type="number" min="1" name="capacity" value="<?=e((string)($edit['capacity']??''))?>"></div><div class="field"><label><input type="checkbox" name="is_published" <?=(!isset($edit)||$edit['is_published'])?'checked':''?>> Published</label></div><?php endif;?></div><div class="field"><label>Featured image</label><input type="file" name="featured_image" accept="image/jpeg,image/png,image/gif,image/webp"></div><button class="btn primary">Save</button><?php if($edit):?><a class="btn ghost" href="content.php?type=<?=$type?>">Cancel</a><?php endif;?></form></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Title</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['title_en']??'')?></td><td><?=e((string)($r['status']??($r['is_published']?'published':'draft')))?></td><td><div class="admin-actions"><a class="btn ghost" href="content.php?type=<?=$type?>&id=<?=$r['id']?>">Edit</a><form method="post"><?=csrfField()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn coral" data-confirm="Delete this item?">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
